// Oh! You Fancy Focaccia — the website and its order book.
//
// The pages under public/ are generated by `npm run build:site`. This server
// serves them, takes orders from the Order page, and runs the admin that
// Amanda works from. Everything that needs the database lives under /api and
// /admin; the rest of the site keeps working without one.
const path = require('path');
const crypto = require('crypto');
const express = require('express');
const helmet = require('helmet');
const compression = require('compression');
const rateLimit = require('express-rate-limit');
const db = require('./db');
const mail = require('./mail');
const { resolveBaseUrl } = require('./base-url');
const demo = require('./demo');

const app = express();
const PORT = process.env.PORT || 3000;
const PUBLIC_DIR = path.join(__dirname, 'public');

app.disable('x-powered-by');
app.set('trust proxy', 1);

// Absolute origin for links that leave the server — the "review & respond"
// button in the order email. Railway injects RAILWAY_PUBLIC_DOMAIN on every
// deploy, so a forgotten BASE_URL still yields a reachable origin.
const BASE_URL = resolveBaseUrl();

// Market days, as the day-of-week numbers Date#getDay uses.
const MARKET_DAYS = [3, 6];
const FULFILLMENTS = ['pickup', 'delivery', 'shipping'];
const ORDER_STATUSES = ['pending', 'accepted', 'declined', 'cancelled', 'completed'];
const PAYMENT_STATUSES = ['unpaid', 'deposit_paid', 'paid', 'refunded'];
const MAX_QTY = 50;

// The design leans on inline style attributes throughout, so style-src has to
// allow them; scripts do not, which is why every script is its own file.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
      fontSrc: ["'self'", 'https://fonts.gstatic.com'],
      imgSrc: ["'self'", 'data:'],
      connectSrc: ["'self'"],
      formAction: ["'self'"],
      frameAncestors: ["'none'"],
      objectSrc: ["'none'"],
      baseUri: ["'self'"],
      upgradeInsecureRequests: [],
    },
  },
  crossOriginEmbedderPolicy: false,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));
app.use(compression());
app.use(express.json({ limit: '64kb' }));

const CANONICAL_HOST = process.env.CANONICAL_HOST;
if (CANONICAL_HOST) {
  app.use((req, res, next) => {
    const host = (req.headers.host || '').toLowerCase().split(':')[0];
    if (host && host !== CANONICAL_HOST && !host.endsWith('.up.railway.app')) {
      return res.redirect(308, `https://${CANONICAL_HOST}${req.originalUrl}`);
    }
    next();
  });
}

app.get('/healthz', (_req, res) => res.status(200).send('ok'));
app.get('/readyz', asyncHandler(async (_req, res) => {
  if (!process.env.DATABASE_URL) return res.status(503).json({ ok: false, reason: 'database_not_configured' });
  try {
    await db.pool.query('SELECT 1');
    return res.json({ ok: true, emailConfigured: mail.configured() });
  } catch (_err) {
    return res.status(503).json({ ok: false, reason: 'database_unavailable' });
  }
}));

// ── helpers ──────────────────────────────────────────────────────────────
function asyncHandler(fn) {
  return (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);
}

async function deliverOutbox(row) {
  try {
    const result = await mail.send({
      to: row.recipient, replyTo: row.reply_to,
      subject: row.subject, html: row.html,
    });
    if (result.sent) await db.markEmailSent(row.id);
    else await db.markEmailFailed(row.id, result.reason);
    return result;
  } catch (err) {
    await db.markEmailFailed(row.id, err.message);
    return { sent: false, reason: err.message };
  }
}

async function queueAndDeliver({ orderId = null, kind, to, replyTo, subject, html }) {
  const row = await db.queueEmail({ orderId, kind, to, replyTo, subject, html });
  return deliverOutbox(row);
}

async function processEmailOutbox() {
  const rows = await db.claimDueEmails(10);
  await Promise.all(rows.map((row) => deliverOutbox(row)));
  return rows.length;
}
// ── push, so a new order reaches Amanda away from the laptop ─────────────
const EXPO_PUSH_URL = 'https://exp.host/--/api/v2/push/send';

// Never throws. A push is a courtesy; the order is the thing that matters,
// and the customer is already waiting on the response.
async function pushNewOrder(order) {
  let tokens;
  try {
    tokens = await db.listPushTokens();
  } catch (err) {
    console.error('Could not read push tokens:', err);
    return;
  }
  if (!tokens.length) return;

  const name = `${order.first_name} ${order.last_name}`.trim();
  const bakes = (order.items || []).reduce((n, it) => n + Number(it.quantity), 0);
  const messages = tokens.map((to) => ({
    to,
    sound: 'default',
    title: 'New order request 🥖',
    body: `${name} — ${bakes} ${bakes === 1 ? 'bake' : 'bakes'} for ${mail.formatDate(order.needed_date)}`,
    data: { type: 'order', orderId: order.id },
  }));

  try {
    const res = await fetch(EXPO_PUSH_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(messages),
    });
    if (!res.ok) {
      console.error('Expo push rejected the request:', res.status);
      return;
    }
    const body = await res.json();
    const tickets = Array.isArray(body?.data) ? body.data : [];
    // One ticket per message, in the order they were sent, so the index is
    // what says which device a failure belongs to.
    await Promise.all(tickets.map(async (ticket, i) => {
      if (ticket?.status !== 'error') return;
      console.error('Push failed for a device:', ticket.message);
      if (ticket.details?.error === 'DeviceNotRegistered') {
        await db.deletePushToken(tokens[i]).catch(() => {});
      }
    }));
  } catch (err) {
    console.error('Could not reach the Expo push service:', err);
  }
}

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
function isIsoDate(v) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(v));
  if (!match) return false;
  const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  return day <= new Date(Date.UTC(year, month, 0)).getUTCDate();
}

function safeEqual(a, b) {
  const ha = crypto.createHash('sha256').update(String(a ?? '')).digest();
  const hb = crypto.createHash('sha256').update(String(b ?? '')).digest();
  return crypto.timingSafeEqual(ha, hb);
}
function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  return `${salt}:${crypto.scryptSync(password, salt, 64).toString('hex')}`;
}
function verifyPassword(password, stored) {
  const [salt, hash] = String(stored ?? '').split(':');
  if (!salt || !hash) return false;
  const a = Buffer.from(hash, 'hex');
  const b = crypto.scryptSync(password, salt, 64);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

// A second credential, for Apple's reviewers. It signs in through the app,
// sees the sample order book in demo.js, and cannot change anything — so no
// real order is touched and no customer's name, phone or address is shown to
// anyone outside the bakery. Unset in normal environments, and then it simply
// does not exist.
const REVIEWER_USERNAME = process.env.REVIEWER_USERNAME || '';
const REVIEWER_PASSWORD = process.env.REVIEWER_PASSWORD || '';
function isReviewer(user, pass) {
  if (!REVIEWER_USERNAME || !REVIEWER_PASSWORD) return false;
  return safeEqual(user, REVIEWER_USERNAME) && safeEqual(pass, REVIEWER_PASSWORD);
}

// The app has no cookie jar, so it presents HTTP Basic on every request. The
// password may itself contain a colon; only the first one separates.
function parseBasicAuth(req) {
  const header = req.headers.authorization || '';
  if (!/^Basic /i.test(header)) return null;
  let decoded;
  try { decoded = Buffer.from(header.slice(6).trim(), 'base64').toString('utf8'); } catch { return null; }
  const colon = decoded.indexOf(':');
  if (colon < 1) return null;
  return { user: decoded.slice(0, colon), pass: decoded.slice(colon + 1) };
}

// Use UTC for the business date so the API and browser calendar agree across
// time zones. The configured notice window is the actual number of days.
function minDateIso(noticeDays) {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() + Math.max(0, noticeDays));
  return db.toIsoDate(d);
}
function isMarketDay(iso) {
  return MARKET_DAYS.includes(new Date(`${iso}T00:00:00`).getDay());
}

// ── sessions ─────────────────────────────────────────────────────────────
// Signed with the stored password hash as the HMAC key: no new secret to
// configure, survives restarts, and changing the password re-keys every
// session, so all of them are invalidated for free.
const SESSION_COOKIE = 'oyff_admin';
const SESSION_TTL_MS = 12 * 60 * 60 * 1000;

function readCookie(req, name) {
  const raw = req.headers.cookie;
  if (!raw) return null;
  for (const part of raw.split(';')) {
    const eq = part.indexOf('=');
    if (eq === -1 || part.slice(0, eq).trim() !== name) continue;
    try { return decodeURIComponent(part.slice(eq + 1).trim()); } catch { return null; }
  }
  return null;
}
function signSession(payload, key) {
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  return `${body}.${crypto.createHmac('sha256', key).update(body).digest('base64url')}`;
}
function verifySession(token, key) {
  if (typeof token !== 'string') return null;
  const dot = token.lastIndexOf('.');
  if (dot < 1) return null;
  const body = token.slice(0, dot);
  const mac = Buffer.from(token.slice(dot + 1));
  const expected = Buffer.from(crypto.createHmac('sha256', key).update(body).digest('base64url'));
  if (mac.length !== expected.length || !crypto.timingSafeEqual(mac, expected)) return null;
  let payload;
  try { payload = JSON.parse(Buffer.from(body, 'base64url').toString()); } catch { return null; }
  if (!payload || typeof payload.exp !== 'number' || Date.now() >= payload.exp) return null;
  return payload;
}
function issueSession(req, res, username, key) {
  res.cookie(SESSION_COOKIE, signSession({ u: username, exp: Date.now() + SESSION_TTL_MS }, key), {
    httpOnly: true, sameSite: 'strict', secure: req.secure, maxAge: SESSION_TTL_MS, path: '/',
  });
}
function wantsHtmlPage(req) {
  return req.method === 'GET' && (req.get('accept') || '').includes('text/html');
}

// Credentials live in the database so the password can be changed from the
// admin. Before any row exists, ADMIN_USERNAME / ADMIN_PASSWORD from the
// environment are the credentials, and the first successful sign-in stores a
// hash of them.
async function checkLogin(username, password) {
  const creds = await db.getAdminCredentials();
  if (creds) {
    if (safeEqual(username, creds.username) && verifyPassword(password, creds.password_hash)) return creds;
    return null;
  }
  const u = process.env.ADMIN_USERNAME, p = process.env.ADMIN_PASSWORD;
  if (!u || !p) return { unconfigured: true };
  if (safeEqual(username, u) && safeEqual(password, p)) {
    const password_hash = hashPassword(p);
    await db.setAdminCredentials(u, password_hash);
    return { username: u, password_hash };
  }
  return null;
}

// Two ways in, and both have to keep working: the browser admin presents the
// session cookie, and Amanda's phone presents Basic on every request because
// it holds no cookie. Basic runs through checkLogin, so a password changed
// from the Settings tab takes effect for the app at the same moment.
async function adminAuth(req, res, next) {
  try {
    const creds = await db.getAdminCredentials();
    const token = readCookie(req, SESSION_COOKIE);
    if (creds && token && verifySession(token, creds.password_hash)) return next();
    const provided = parseBasicAuth(req);
    if (provided) {
      if (isReviewer(provided.user, provided.pass)) {
        req.readOnly = true;
        return next();
      }
      const result = await checkLogin(provided.user, provided.pass);
      if (result && !result.unconfigured) return next();
    }
  } catch (err) {
    return next(err);
  }
  if (wantsHtmlPage(req)) return res.redirect(302, '/admin/login');
  return res.status(401).json({ error: 'Sign in to continue.' });
}

// ── rate limits ──────────────────────────────────────────────────────────
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, limit: Number(process.env.API_RATE_LIMIT) || 300,
  standardHeaders: true, legacyHeaders: false,
});
const writeLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, limit: Number(process.env.WRITE_RATE_LIMIT) || 8,
  standardHeaders: true, legacyHeaders: false,
  message: { error: 'Too many requests. Please try again in a little while.' },
});
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, limit: Number(process.env.LOGIN_RATE_LIMIT) || 10,
  skipSuccessfulRequests: true, standardHeaders: true, legacyHeaders: false,
  message: { error: 'Too many sign-in attempts. Please try again later.' },
});
// The app sends credentials on every single request, so counting the
// successful ones would lock Amanda out in the middle of a market morning.
// Only failures are budgeted, and a request carrying nothing at all is just a
// browser on its way to the sign-in page.
const adminAuthLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, limit: Number(process.env.ADMIN_RATE_LIMIT) || 20,
  skipSuccessfulRequests: true,
  // Only a rejected credential spends the budget. Counting every failed
  // response would let a morning of ordinary validation mistakes — a blank
  // name, a bad date — lock Amanda out of her own order book.
  requestWasSuccessful: (_req, res) => res.statusCode !== 401,
  skip: (req) => !req.headers.authorization && !readCookie(req, SESSION_COOKIE),
  standardHeaders: true, legacyHeaders: false,
  message: { error: 'Too many attempts. Please try again later.' },
});

// Without a database there is no order book. The pages still serve; the
// order form and the admin say so plainly instead of throwing.
app.use(['/api', '/admin', '/respond'], (req, res, next) => {
  if (process.env.DATABASE_URL) return next();
  if (wantsHtmlPage(req)) return res.status(503).send('Ordering is not set up yet.');
  res.status(503).json({ error: 'Ordering is not set up yet. Please email us instead.' });
});
app.use(['/api', '/respond'], apiLimiter);

// ── admin sign-in ────────────────────────────────────────────────────────
app.get('/admin/login', (_req, res) => res.sendFile(path.join(PUBLIC_DIR, 'admin-login.html')));

app.post('/admin/login', loginLimiter, asyncHandler(async (req, res) => {
  const result = await checkLogin(str(req.body?.username), String(req.body?.password ?? ''));
  if (result?.unconfigured) return res.status(500).json({ error: 'Admin sign-in is not configured.' });
  if (!result) return res.status(401).json({ error: 'Incorrect username or password.' });
  issueSession(req, res, result.username, result.password_hash);
  res.json({ ok: true });
}));

app.post('/admin/logout', (_req, res) => {
  res.clearCookie(SESSION_COOKIE, { path: '/' });
  res.status(204).end();
});

app.use(['/admin', '/admin.html', '/api/admin'], adminAuthLimiter, adminAuth);
app.get('/admin', (_req, res) => res.sendFile(path.join(PUBLIC_DIR, 'admin.html')));

// Who is signed in, and whether they may change anything. The app asks on
// launch so it can say so plainly instead of letting a button fail.
app.get('/api/admin/session', asyncHandler(async (req, res) => {
  if (req.readOnly) return res.json({ username: REVIEWER_USERNAME, readOnly: true });
  const creds = await db.getAdminCredentials();
  res.json({ username: creds ? creds.username : process.env.ADMIN_USERNAME || null, readOnly: false });
}));

// Everything below this point is the real order book. The reviewer account
// never reaches it: writes are refused, and reads are answered from the sample
// data. An endpoint added later answers empty until it is described in
// demo.js, which is the safe way round.
app.use('/api/admin', (req, res, next) => {
  if (!req.readOnly) return next();
  if (req.method !== 'GET') {
    return res.status(403).json({ error: 'This is the App Review account, so it can look but not change anything.' });
  }
  res.json(demo.responseFor(req.path));
});

// ── the app's push registration ──────────────────────────────────────────
// The app registers on every launch, so this doubles as a heartbeat. Only
// Expo's own token format is stored; anything else is refused here rather
// than kept and left to fail later at send time.
app.post('/api/admin/push-token', asyncHandler(async (req, res) => {
  const token = str(req.body?.token);
  if (!/^Expo(nent)?PushToken\[[^\]]+\]$/.test(token)) {
    return res.status(400).json({ error: 'That is not an Expo push token.' });
  }
  await db.savePushToken(token);
  res.json({ ok: true });
}));

// Signing out, or turning notifications off, should actually stop them.
app.delete('/api/admin/push-token', asyncHandler(async (req, res) => {
  const token = str(req.body?.token);
  if (token) await db.deletePushToken(token);
  res.json({ ok: true });
}));

// ── public API ───────────────────────────────────────────────────────────
app.get('/api/menu', asyncHandler(async (_req, res) => {
  const [items, settings] = await Promise.all([db.listMenu({ availableOnly: true }), db.getSettings()]);
  res.json({
    courses: db.COURSES,
    items: items.map((m) => ({ id: m.id, course: m.course, name: m.name, description: m.description, price: m.price, image: m.image })),
    paymentInstructions: settings.payment_instructions,
  });
}));

app.get('/api/availability', asyncHandler(async (_req, res) => {
  const [blocked, settings] = await Promise.all([db.getBlockedRanges(), db.getSettings()]);
  res.json({
    minNoticeDays: Number(settings.min_notice_days) || 0,
    marketDays: MARKET_DAYS,
    shippingFee: Number(settings.shipping_fee) || 0,
    pickupNote: settings.pickup_note,
    blocked: blocked.map(({ start, end }) => ({ start, end })),
  });
}));

// Checks the parts of an order that are the same whether it came from the
// website or was typed in by Amanda. Returns { error } or { order, items }.
async function prepareOrder(body, { website }) {
  const order = {
    firstName: str(body.firstName), lastName: str(body.lastName),
    email: str(body.email).toLowerCase(), phone: str(body.phone),
    fulfillment: str(body.fulfillment) || 'pickup', neededDate: str(body.neededDate),
    address: str(body.address), notes: str(body.notes),
  };
  if (!order.firstName || !order.lastName) return { error: 'Please tell us your first and last name.' };
  if (website && !order.email) return { error: 'Please enter an email address so we can confirm your order.' };
  if (!order.email && !order.phone) return { error: 'An email address or phone number is required.' };
  if (order.email && !isEmail(order.email)) return { error: 'That email address does not look right.' };
  if (!FULFILLMENTS.includes(order.fulfillment)) return { error: 'Choose pickup, delivery or shipping.' };
  if (order.fulfillment !== 'pickup' && !order.address) return { error: 'Please give us an address for delivery or shipping.' };
  if (!isIsoDate(order.neededDate)) return { error: 'Please choose a date.' };
  if (order.notes.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  const requested = Array.isArray(body.items) ? body.items : [];
  if (!requested.length) return { error: 'Add at least one item to your order.' };
  const wanted = new Map();
  for (const it of requested) {
    const id = Number(it?.id), qty = Number(it?.quantity);
    if (!Number.isInteger(id) || !Number.isInteger(qty) || qty < 1 || qty > MAX_QTY) {
      return { error: `Quantities must be whole numbers between 1 and ${MAX_QTY}.` };
    }
    const total = (wanted.get(id) || 0) + qty;
    if (total > MAX_QTY) return { error: `Quantities must be whole numbers between 1 and ${MAX_QTY}.` };
    wanted.set(id, total);
  }
  const menu = await db.getMenuItems([...wanted.keys()]);
  const byId = new Map(menu.map((m) => [m.id, m]));
  const items = [];
  for (const [id, quantity] of wanted) {
    const m = byId.get(id);
    if (!m || (website && !m.available)) return { error: 'One of those items is not available right now. Please refresh the menu.' };
    items.push({ menuItemId: m.id, name: m.name, unitPrice: m.price, quantity });
  }
  // Shipping is flat, and charged at whatever the fee is the moment the order
  // is taken. The settings come back with it so the caller does not read them
  // a second time.
  const settings = await db.getSettings();
  order.shippingFee = order.fulfillment === 'shipping' ? Number(settings.shipping_fee) || 0 : 0;
  // Amanda should not be adding up her own bill of fare. Every priced item
  // plus the fee is the total, worked out here so it is on the order the
  // moment it arrives. One item quoted on request and there is no total to
  // state — it stays empty and she fills it in, which is the only case left
  // where she has to.
  order.amount = itemsTotal(items) === null ? null : itemsTotal(items) + order.shippingFee;
  return { order, items, settings };
}

// null when anything is unpriced, because a partial sum is a wrong total.
function itemsTotal(items) {
  let sum = 0;
  for (const it of items) {
    const price = it.unitPrice ?? it.unit_price;
    if (price === null || price === undefined || price === '') return null;
    sum += Number(price) * it.quantity;
  }
  return sum;
}

app.post('/api/order', writeLimiter, asyncHandler(async (req, res) => {
  const idempotencyKey = str(req.get('Idempotency-Key'));
  if (idempotencyKey.length > 128) return res.status(400).json({ error: 'The idempotency key is too long.' });
  const prepared = await prepareOrder(req.body || {}, { website: true });
  if (prepared.error) return res.status(400).json({ error: prepared.error });
  const { order, items, settings } = prepared;

  const notice = Number(settings.min_notice_days) || 0;
  if (order.neededDate < minDateIso(notice)) {
    return res.status(400).json({ error: notice > 0 ? `Please choose a date at least ${notice} day${notice === 1 ? '' : 's'} from today.` : 'Please choose a date from today onwards.' });
  }
  if (order.fulfillment === 'pickup' && !isMarketDay(order.neededDate)) {
    return res.status(400).json({ error: 'Market pickup is on Wednesdays and Saturdays. Please choose one of those days.' });
  }
  if (await db.isDateBlocked(order.neededDate)) {
    return res.status(409).json({ error: 'We are not baking that day. Please choose another date.' });
  }

  const saved = await db.createOrder({ ...order, idempotencyKey: idempotencyKey || null }, items);
  if (saved.duplicate) return res.status(201).json({ ok: true, orderId: saved.id, emailSent: false, duplicate: true });
  const full = await db.getOrder(saved.id);
  const respondUrl = `${BASE_URL}/respond/${saved.id}?token=${saved.respond_token}`;
  const [notice1, thanks] = await Promise.all([
    queueAndDeliver({ orderId: saved.id, kind: 'order_notice', to: mail.ORDERS_INBOX, replyTo: mail.INFO_EMAIL, ...mail.buildBakeryNotice(full, respondUrl) }),
    queueAndDeliver({ orderId: saved.id, kind: 'order_thank_you', to: order.email, replyTo: mail.INFO_EMAIL, ...mail.buildThankYou(full, settings) }),
  ]);
  // Deliberately not awaited alongside the emails: the push must never hold
  // up or fail the response the customer is waiting on.
  pushNewOrder(full);
  res.status(201).json({ ok: true, orderId: saved.id, emailSent: thanks.sent && notice1.sent });
}));

app.get('/api/reviews', asyncHandler(async (_req, res) => {
  res.json({ reviews: await db.listApprovedReviews() });
}));

app.post('/api/reviews', writeLimiter, asyncHandler(async (req, res) => {
  const name = str(req.body?.name), review = str(req.body?.review), rating = Number(req.body?.rating);
  if (str(req.body?.website)) return res.status(400).json({ error: 'That review could not be submitted.' });
  if (!name) return res.status(400).json({ error: 'Please tell us your name.' });
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) return res.status(400).json({ error: 'Pick a rating from 1 to 5.' });
  if (!review) return res.status(400).json({ error: 'Please write a few words.' });
  if (review.length > 2000) return res.status(400).json({ error: 'Reviews are limited to 2000 characters.' });
  const saved = await db.createReview({ name, rating, review });
  const notice = await queueAndDeliver({ kind: 'review_notice', to: mail.INFO_EMAIL, replyTo: mail.INFO_EMAIL, ...mail.buildReviewNotice(saved) });
  res.status(201).json({ ok: true, review: { id: saved.id }, emailSent: notice.sent });
}));

// ── respond from the email ───────────────────────────────────────────────
async function respondToOrder(id, action) {
  const order = await db.getOrder(id);
  if (!order) return { status: 404, error: 'Order not found' };
  if (order.status !== 'pending') return { status: 409, error: `This order is already ${order.status}.` };
  if (action === 'accept' && await db.isDateBlocked(db.toIsoDate(order.needed_date))) {
    return { status: 409, error: 'That date is blocked. Unblock it first, or change the date.' };
  }
  return { order: await db.setOrderStatus(id, action === 'accept' ? 'accepted' : 'declined') };
}

function renderRespondPage(order) {
  const e = mail.escapeHtml;
  const head = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Order — ${mail.BAKERY_NAME}</title><link rel="stylesheet" href="/style.css"></head>`;
  if (!order) {
    return `${head}<body style="padding:var(--s16) var(--s5);text-align:center"><h2>Link not valid</h2><p style="opacity:.7">This link is invalid or has expired.</p></body></html>`;
  }
  const done = order.status !== 'pending';
  const items = order.items.map((it) => `<li class="fare" style="justify-content:space-between"><span>${e(it.name)}</span><span>&times; ${it.quantity}</span></li>`).join('');
  return `${head}<body style="padding:var(--s10) var(--s5)">
  <div style="max-width:560px;margin:0 auto;background:var(--paper-2);border:1px solid var(--rule);padding:var(--s8)">
    <p class="caps" style="color:var(--olive)">Order #${order.id}</p>
    <h2 style="font-size:var(--xl);margin-block:var(--s2) var(--s5)">${e(order.first_name)} ${e(order.last_name)}</h2>
    <p><strong>${e(mail.FULFILLMENT_LABELS[order.fulfillment] || order.fulfillment)}</strong><br>${e(mail.formatDate(order.needed_date))}</p>
    ${order.address ? `<p>${e(order.address)}</p>` : ''}
    <ul style="margin-block:var(--s5)">${items}</ul>
    ${order.notes ? `<p style="font-style:italic;opacity:.8">${e(order.notes)}</p>` : ''}
    <p style="font-size:var(--sm);opacity:.7;margin-top:var(--s4)">${e(order.email || '')} ${e(order.phone || '')}</p>
    ${done ? `<p style="margin-top:var(--s6)"><strong>This order is already ${e(order.status)}.</strong></p>`
           : `<div id="respond" data-id="${order.id}" data-token="${e(order.respond_token)}" style="display:flex;gap:var(--s4);margin-top:var(--s6)">
                <button class="btn btn-fill" data-action="accept" style="flex:1">Accept</button>
                <button class="btn btn-line" data-action="decline" style="flex:1">Decline</button></div>
              <p id="respond-msg" style="margin-top:var(--s4);display:none"></p>`}
    <p style="margin-top:var(--s8)"><a href="/admin" class="caps">Open the admin</a></p>
  </div><script src="/respond.js"></script></body></html>`;
}

app.get('/respond/:id', asyncHandler(async (req, res) => {
  const order = await db.getOrder(req.params.id);
  const token = req.query.token;
  if (!order || !token || !safeEqual(token, order.respond_token)) return res.status(404).send(renderRespondPage(null));
  res.send(renderRespondPage(order));
}));

app.post('/api/orders/:id/respond', asyncHandler(async (req, res) => {
  const { action, token } = req.body || {};
  if (!['accept', 'decline'].includes(action)) return res.status(400).json({ error: 'Invalid action' });
  const order = await db.getOrder(req.params.id);
  if (!order || !token || !safeEqual(token, order.respond_token)) return res.status(404).json({ error: 'Order not found' });
  const result = await respondToOrder(req.params.id, action);
  if (result.error) return res.status(result.status).json({ error: result.error });
  res.json({ ok: true, status: result.order.status });
}));

