app.patch('/api/admin/orders/:id', asyncHandler(async (req, res) => {
  const current = await db.getOrder(req.params.id);
  if (!current) return res.status(404).json({ error: 'Order not found' });
  const body = req.body || {};
  const patch = {};
  for (const key of ['firstName', 'lastName', 'email', 'phone', 'fulfillment', 'neededDate', 'address', 'notes']) {
    if (Object.prototype.hasOwnProperty.call(body, key)) patch[key] = body[key];
  }
  if (!Object.keys(patch).length) return res.status(400).json({ error: 'Nothing to change.' });
  const merged = {
    firstName: current.first_name, lastName: current.last_name, email: current.email || '', phone: current.phone || '',
    fulfillment: current.fulfillment, neededDate: db.toIsoDate(current.needed_date), address: current.address || '',
    notes: current.notes || '', ...Object.fromEntries(Object.entries(patch).map(([k, v]) => [k, str(v)])),
  };
  if (!merged.firstName || !merged.lastName) return res.status(400).json({ error: 'First and last name are required.' });
  if (!merged.email && !merged.phone) return res.status(400).json({ error: 'An email address or phone number is required.' });
  if (merged.email && !isEmail(merged.email)) return res.status(400).json({ error: 'That email address does not look right.' });
  if (!FULFILLMENTS.includes(merged.fulfillment)) return res.status(400).json({ error: 'Choose pickup, delivery or shipping.' });
  if (!isIsoDate(merged.neededDate)) return res.status(400).json({ error: 'Date must be a real calendar date.' });
  // shipping_fee was snapshotted when the order arrived. Changing how it is
  // fulfilled has to move it too, or a pickup keeps a phantom shipping line on
  // its next confirmation and an order moved to shipping is charged nothing.
  if (merged.fulfillment !== current.fulfillment) {
    const settings = merged.fulfillment === 'shipping' ? await db.getSettings() : null;
    const nextFee = settings ? Number(settings.shipping_fee) || 0 : 0;
    patch.shippingFee = nextFee;
    // Keep the total in step with the fee, but only while it is still the one
    // we worked out. The moment Amanda types her own figure it is hers, and
    // moving an order between pickup and shipping must not overwrite it.
    const goods = itemsTotal(current.items || []);
    const untouched = goods !== null && current.amount !== null
      && Number(current.amount) === goods + (Number(current.shipping_fee) || 0);
    if (untouched) patch.amount = goods + nextFee;
  }
  const updated = await db.updateOrder(req.params.id, patch);
  // A changed total changes what is owed, and that is derived from the money.
  res.json({ ok: true, order: patch.amount === undefined ? updated : await db.recomputeOrderPayment(req.params.id) });
}));

