// The three sends. None of them goes out on its own.
async function sendForOrder(req, res, build) {
  const order = await db.getOrder(req.params.id);
  if (!order) return res.status(404).json({ error: 'Order not found' });
  if (!order.email) return res.status(400).json({ error: 'This order has no email address.' });
  if (!mail.configured()) return res.status(503).json({ error: 'Email is not set up yet (RESEND_API_KEY is missing).' });
  const built = await build(order);
  if (built.error) return res.status(400).json({ error: built.error });
  const result = await queueAndDeliver({ orderId: order.id, kind: 'admin_' + built.subject.slice(0, 30), to: order.email, replyTo: mail.INFO_EMAIL, ...built });
  if (!result.sent) return res.status(502).json({ error: `Could not send: ${result.reason}` });
  res.json({ ok: true });
}

app.post('/api/admin/orders/:id/confirmation', asyncHandler((req, res) =>
  sendForOrder(req, res, async (order) => mail.buildConfirmation(order, await db.getSettings()))));

app.post('/api/admin/orders/:id/receipt', asyncHandler((req, res) =>
  sendForOrder(req, res, async (order) => {
    if (!order.payments.length) return { error: 'Record the payment first — none is saved on this order.' };
    const { paymentId } = req.body || {};
    const payment = paymentId ? order.payments.find((p) => String(p.id) === String(paymentId)) : order.payments[0];
    if (!payment) return { error: 'That payment is not on this order.' };
    return mail.buildReceipt(order, payment, await db.getSettings());
  })));

app.post('/api/admin/orders/:id/email', asyncHandler((req, res) => {
  const subject = str(req.body?.subject), message = str(req.body?.message);
  if (!subject || !message) return res.status(400).json({ error: 'Subject and message are required.' });
  return sendForOrder(req, res, async () => mail.buildPlain(subject, message, await db.getSettings()));
}));

// ── admin API: menu ──────────────────────────────────────────────────────
function menuFields(body, { partial }) {
  const out = {};
  const has = (k) => Object.prototype.hasOwnProperty.call(body, k);
  if (!partial || has('course')) {
    out.course = str(body.course);
    if (!db.COURSES[out.course]) return { error: 'Pick a course for this item.' };
  }
  if (!partial || has('name')) {
    out.name = str(body.name);
    if (!out.name) return { error: 'Give the item a name.' };
    if (out.name.length > 120) return { error: 'Names are limited to 120 characters.' };
  }
  if (has('description')) out.description = str(body.description) || null;
  if (has('price')) {
    const p = body.price === null || body.price === '' ? null : Number(body.price);
    if (p !== null && (!Number.isFinite(p) || p < 0)) return { error: 'Price must be a number, zero or more.' };
    out.price = p;
  }
  if (has('image')) {
    const v = str(body.image).trim();
    // A bare file name from public/img and nothing else. It is written into a
    // src attribute on the order page, so a path or a URL from here must not
    // be able to point it somewhere other than our own images.
    if (!v) out.image = null;
    else if (!/^[A-Za-z0-9][A-Za-z0-9._-]*\.(webp|jpg|jpeg|png)$/.test(v)) {
      return { error: 'Image must be a file name in public/img, like savory-round.webp.' };
    } else out.image = v;
  }
  if (has('available')) out.available = Boolean(body.available);
  if (has('sortOrder')) {
    const n = Number(body.sortOrder);
    if (!Number.isInteger(n)) return { error: 'Sort order must be a whole number.' };
    out.sortOrder = n;
  }
  return { fields: out };
}

