app.put('/api/admin/settings', asyncHandler(async (req, res) => {
  const body = req.body || {};
  const patch = {};
  if ('deposit_percent' in body) {
    const n = Number(body.deposit_percent);
    if (!Number.isInteger(n) || n < 0 || n > 100) return res.status(400).json({ error: 'Deposit must be a whole percentage from 0 to 100.' });
    patch.deposit_percent = String(n);
  }
  if ('min_notice_days' in body) {
    const n = Number(body.min_notice_days);
    if (!Number.isInteger(n) || n < 0 || n > 60) return res.status(400).json({ error: 'Notice must be a whole number of days, 0 to 60.' });
    patch.min_notice_days = String(n);
  }
  if ('shipping_fee' in body) {
    const n = Number(body.shipping_fee);
    if (!Number.isFinite(n) || n < 0 || n > 1000) return res.status(400).json({ error: 'Shipping must be an amount from 0 to 1000.' });
    patch.shipping_fee = n.toFixed(2);
  }
  // Emptiable — clearing the handle is how the block comes out of the emails
  // again, so the not-empty rule below cannot apply to it.
  if ('venmo_handle' in body) {
    const v = str(body.venmo_handle);
    if (v.length > 200) return res.status(400).json({ error: 'That is limited to 200 characters.' });
    patch.venmo_handle = v;
  }
  if ('apple_pay_accepted' in body) {
    const v = body.apple_pay_accepted;
    patch.apple_pay_accepted = (v === true || v === 1 || v === '1' || v === 'true') ? '1' : '';
  }
  for (const key of ['payment_instructions', 'pickup_note']) {
    if (!(key in body)) continue;
    const v = str(body[key]);
    if (!v) return res.status(400).json({ error: 'That text cannot be empty.' });
    if (v.length > 1000) return res.status(400).json({ error: 'That text is limited to 1000 characters.' });
    patch[key] = v;
  }
  res.json({ ok: true, settings: await db.setSettings(patch) });
}));

app.post('/api/admin/password', asyncHandler(async (req, res) => {
  const { currentPassword, newPassword } = req.body || {};
  if (!currentPassword || !newPassword || String(newPassword).length < 8) {
    return res.status(400).json({ error: 'Enter the current password and a new one of at least 8 characters.' });
  }
  const creds = await db.getAdminCredentials();
  if (!creds || !verifyPassword(currentPassword, creds.password_hash)) return res.status(401).json({ error: 'The current password is incorrect.' });
  await db.setAdminCredentials(creds.username, hashPassword(newPassword));
  res.json({ ok: true });
}));

